  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Shop Machines', path: '/shop' },
    { name: 'Services', path: '/services' },
    { name: 'Contact', path: '/contact' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <header className="sticky top-0 z-40 bg-white shadow-md">
      {/* Top Bar */}
      <div className="bg-agro-green text-white py-2 px-4 text-sm hidden md:block">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <p>📍 Nakuru Industrial Area, Near Pivot Hotel</p>
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <Phone size={14} /> Call us: {PHONE_NUMBER}
            </span>
            <span className="font-semibold bg-agro-orange px-2 py-0.5 rounded text-xs">PAY ON DELIVERY</span>
          </div>
        </div>
      </div>

      {/* Main Nav */}
      <div className="max-w-7xl mx-auto px-4 py-4">
        <div className="flex justify-between items-center">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-2" onClick={() => setIsMenuOpen(false)}>
            <div className="bg-agro-green p-2 rounded-lg">
              <span className="text-white font-bold text-xl">AF</span>
            </div>
            <div className="flex flex-col">
              <span className="text-xl font-bold text-gray-900 leading-none">Agro Farm</span>
              <span className="text-xs text-agro-green font-medium">Machineries & Supplies</span>
            </div>
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`text-sm font-medium hover:text-agro-green transition-colors ${isActive(link.path) ? 'text-agro-green font-bold' : 'text-gray-600'}`}
              >
                {link.name}
              </Link>
            ))}
          </nav>

          {/* Actions */}
          <div className="flex items-center gap-4">
            <Link to="/shop" className="text-gray-600 hover:text-agro-green">
              <Search size={24} />
            </Link>
            <div className="relative">
              <ShoppingCart size={24} className="text-gray-600" />
