import React, { useState, useEffect } from 'react';
import { PRODUCTS, CATEGORIES } from '../constants';
import ProductCard from '../components/ProductCard';
import { Filter } from 'lucide-react';

const Shop: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState('All');

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const filteredProducts = activeCategory === 'All' 
    ? PRODUCTS 
    : PRODUCTS.filter(p => p.category === activeCategory);

  const categoryNames = ['All', ...CATEGORIES.map(c => c.name)];

  return (
    <div className="bg-agro-cream min-h-screen py-8">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row gap-8">

          {/* Sidebar / Filters */}
          <div className="w-full md:w-64 flex-shrink-0">
            <div className="bg-white p-6 rounded-xl shadow-sm sticky top-24">
              <div className="flex items-center gap-2 mb-4 text-gray-900">
                <Filter size={20} />
                <h3 className="font-bold text-lg">Filters</h3>
              </div>

              <div className="mb-6">
                <h4 className="font-semibold mb-3 text-sm text-gray-500 uppercase">Categories</h4>
                <div className="flex flex-col gap-2">
                  {categoryNames.map(cat => (
                    <button
                      key={cat}
                      onClick={() => setActiveCategory(cat)}
                      className={`text-left px-3 py-2 rounded-lg text-sm transition-colors ${activeCategory === cat ? 'bg-agro-green text-white font-medium' : 'hover:bg-gray-100 text-gray-700'}`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>

              <div className="mb-6">
                <h4 className="font-semibold mb-3 text-sm text-gray-500 uppercase">Power Source</h4>
                <div className="space-y-2">
                  <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                    <input type="checkbox" className="rounded text-agro-green focus:ring-agro-green" /> Diesel
                  </label>
                  <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                    <input type="checkbox" className="rounded text-agro-green focus:ring-agro-green" /> Electric
                  </label>
                  <label className="flex items-center gap-2 text-sm text-gray-700 cursor-pointer">
                    <input type="checkbox" className="rounded text-agro-green focus:ring-agro-green" /> Petrol
                  </label>
                </div>
              </div>
            </div>
          </div>

          {/* Product Grid */}
          <div className="flex-grow">
            <div className="flex justify-between items-center mb-6">
              <h1 className="text-2xl font-bold text-gray-900">{activeCategory} Machinery</h1>
              <span className="text-gray-500 text-sm">{filteredProducts.length} Results</span>
            </div>

            {filteredProducts.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.map(product => (
                  <ProductCard key={product.id} product={product} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-white rounded-xl">
                <p className="text-gray-500 text-lg">No products found in this category.</p>
                <button onClick={() => setActiveCategory('All')} className="mt-4 text-agro-green font-medium hover:underline">
                  View all products
                </button>
              </div>
            )}

            {/* Load More Mockup */}
            {filteredProducts.length > 0 && (
              <div className="mt-12 text-center">
                <button className="bg-white border border-gray-300 text-gray-700 px-6 py-3 rounded-lg font-medium hover:bg-gray-50 transition-colors">
                  Load More Machines
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Shop;

import React, { useEffect, useState } from 'react';
